// ============================================================
//  DOT BO SUNG 3 30/10/2026 — chuan hoa mock (khong xoa noi dung cu).
//  TOEIC: gan Part cho mock cu (Nghe: doi thoai Man/Woman = Part 3, doc thoai dai = Part 4,
//  con lai = Part 2; Doc: co passage = Part 7, khong passage = Part 5), them mock moi,
//  sap xep theo thu tu Part, xoay phuong an de dap an khong don mot vi tri.
//  TOPIK II: them 25 Nghe + 25 Doc + Viet 52/54 -> du 104 nhiem vu; xoay dap an trac nghiem.
//  HSK: them doan Nghe/bai Doc/bai Viet moi; xoay dap an cac cau hoi Nghe/Doc/Viet
//  (dap an dung van giu nguyen theo dap an cu, chi doi vi tri lua chon).
// ============================================================
(function () {
  function rot(q, shift) {
    var o = q.o; if (!o || o.length < 2) return;
    var s = ((shift % o.length) + o.length) % o.length; if (!s) return;
    q.o = o.slice(s).concat(o.slice(0, s));
    q.a = (q.a - s + o.length) % o.length;
  }
  function bucketL(q) {
    var s = q.script || "";
    if (s.indexOf("Man:") >= 0 && s.indexOf("Woman:") >= 0) return 3;
    if (s.length > 150) return 4;
    return 2;
  }
  TC_MOCK_L.forEach(function (q) { if (!q.part) q.part = bucketL(q); });
  TC_MOCK_R.forEach(function (q) { if (!q.part) q.part = q.passage ? 7 : 5; });
  TC_MOCK_L.push.apply(TC_MOCK_L, TC_MOCK3_L);
  TC_MOCK_R.push.apply(TC_MOCK_R, TC_MOCK3_R);
  function byPart(arr, order) {
    var out = [];
    order.forEach(function (p) { arr.forEach(function (q) { if (q.part === p) out.push(q); }); });
    return out;
  }
  TC_MOCK_L = byPart(TC_MOCK_L, [1, 2, 3, 4]);
  TC_MOCK_R = byPart(TC_MOCK_R, [5, 6, 7]);
  TC_MOCK_L.forEach(function (q, i) { rot(q, i); });
  TC_MOCK_R.forEach(function (q, i) { rot(q, i); });
  TP_MOCK2_L.push.apply(TP_MOCK2_L, TP_MOCK3_L);
  TP_MOCK2_R.push.apply(TP_MOCK2_R, TP_MOCK3_R);
  TP_MOCK2_W.push.apply(TP_MOCK2_W, TP_MOCK3_W);
  TP_MOCK2_L.forEach(function (q, i) { rot(q, i); });
  TP_MOCK2_R.forEach(function (q, i) { rot(q, i); });
  ZH_LISTENING.push.apply(ZH_LISTENING, ZH_LISTEN_EXPAND3);
  ZH_READING.push.apply(ZH_READING, ZH_READ_EXPAND3);
  ZH_WRITE.push.apply(ZH_WRITE, ZH_WRITE_EXPAND3);
  var qi = 0;
  ZH_LISTENING.forEach(function (s) { (s.questions || []).forEach(function (q) { rot(q, qi++); }); });
  ZH_READING.forEach(function (s) { (s.questions || []).forEach(function (q) { rot(q, qi++); }); });
  ZH_WRITE.forEach(function (w) { (w.questions || []).forEach(function (q) { rot(q, qi++); }); });
})();

// DOT 3b 30/10/2026 — xoay lai dap an TOPIK II theo ma noi dung cau (khong theo chi so),
// vi xoay theo chi so van don dap an: dap an cu tuong quan voi chi so. Chi doi vi tri
// lua chon, dap an dung khong doi.
(function () {
  function rot(q, shift) {
    var o = q.o; if (!o || o.length < 2) return;
    var s = ((shift % o.length) + o.length) % o.length; if (!s) return;
    q.o = o.slice(s).concat(o.slice(0, s));
    q.a = (q.a - s + o.length) % o.length;
  }
  function hash(s) { var h = 0; for (var i = 0; i < s.length; i++) h += s.charCodeAt(i); return h; }
  TP_MOCK2_L.forEach(function (q) { rot(q, hash(q.script || "") + hash(q.q || "")); });
  TP_MOCK2_R.forEach(function (q) { rot(q, hash(q.q || "")); });
})();
